fn cleanupRuntimeConfig(runtime: *RuntimeConfig) void {
    const allocator = runtime.allocator;
    runtime.deinit();
    allocator.destroy(runtime);
}

fn cleanupDataPaths(paths: *DataPaths) void {
    const allocator = paths.allocator;
    paths.deinit();
    allocator.destroy(paths);
}

const AiHost = struct {
    const PendingAiCompletion = struct {
        context: @import("ai/host_tools.zig").Context,
        owner: @import("host/identity.zig").ContentOwner,
        operation: u64,
        turn: u64,
        completion: @import("host/notification_host.zig").AiCompletion,
        detail: [1400]u8 = @splat(0),
